"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface PulseDotProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: "green" | "amber" | "red" | "accent" | "blue" | "neutral";
  size?: number;
  /** Zet de kloppende animatie uit; de halo blijft. */
  still?: boolean;
  label?: string;
}

/** PulseDot — statusbolletje met halo, voor "live", "bezet" of "online". */
export const PulseDot = React.forwardRef<HTMLSpanElement, PulseDotProps>(function PulseDot(
  { tone = "green", size = 9, still, label, className, style, ...rest },
  ref
) {
  return (
    <span
      ref={ref}
      role={label ? "status" : undefined}
      aria-label={label}
      className={cn("lui-pulse", `lui-pulse-${tone}`, still && "lui-pulse-still", className)}
      style={{ width: size, height: size, ...style }}
      {...rest}
    />
  );
});

/* ============================ PulseDot ============================ */
.lui-pulse {
  --lui-pulse-color: var(--green);
  position: relative; display: inline-block; flex: none;
  border-radius: var(--r-full); background: var(--lui-pulse-color);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--lui-pulse-color) 18%, transparent);
}
.lui-pulse::after {
  content: ""; position: absolute; inset: 0;
  border-radius: inherit; background: var(--lui-pulse-color);
  animation: lui-pulse 1.8s var(--ease-out) infinite;
}
.lui-pulse-still::after { animation: none; display: none; }

@keyframes lui-pulse {
  0% { opacity: .55; transform: scale(1); }
  70% { opacity: 0; transform: scale(2.4); }
  100% { opacity: 0; transform: scale(2.4); }
}

.lui-pulse-green { --lui-pulse-color: var(--green); }
.lui-pulse-amber { --lui-pulse-color: var(--amber); }
.lui-pulse-red { --lui-pulse-color: var(--red); }
.lui-pulse-accent { --lui-pulse-color: var(--accent); }
.lui-pulse-blue { --lui-pulse-color: var(--blue); }
.lui-pulse-neutral { --lui-pulse-color: var(--text-3); }
